#!/usr/bin/env powershell
# Jarvis baslatici
$base64 = ""
if (-not (Test-Path "jarvis.yaml")) {
    [System.IO.File]::WriteAllBytes("jarvis.yaml", [Convert]::FromBase64String($base64))
    Write-Host "jarvis.yaml olusturuldu" -ForegroundColor Green
} else {
    Write-Host "jarvis.yaml mevcut, kullaniliyor" -ForegroundColor Yellow
}
.\docker-agent.exe run jarvis.yaml --yolo
